#!/usr/bin/env python3
"""Génère 00-Pilotage/Exigences-origine.md depuis Matrice-exigences.csv et le tableau d'origines ci-dessous.
Le sujet officiel n'est pas dans le dossier (B-10) : les origines citent le brief du commanditaire (« brief §n », première instruction de la mission) et le LISEZ-MOI fourni."""
import csv, os
B = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
M = {r["id"]: r for r in csv.DictReader(open(os.path.join(B, "00-Pilotage", "Matrice-exigences.csv"), encoding="utf-8"))}
O = {
 "REQ-01": "brief §6 (inventaire, 40 IoC annoncés) ; §5 `Inventaire-IoC.csv`", "REQ-02": "brief §6 (12 alertes) ; §5 `Inventaire-alertes.csv`", "REQ-03": "brief §6 (3 binaires) ; §5 `Inventaire-binaires.csv`",
 "REQ-04": "brief §6 (« vérifie les empreintes, analyses statiques accessibles ») ; LISEZ-MOI : échantillons non fournis", "REQ-05": "brief §5 `Integrite-et-provenance.md`, §6 (traçabilité, hash)", "REQ-06": "brief §5 `Registre-sources.csv`, `Journal-collecte.csv`",
 "REQ-07": "brief §5 `Note-cadrage`, §11 (2 pages, fin J1)", "REQ-08": "brief §2 (5 jours, 35 h), §5 `Planning-35h.md`", "REQ-09": "brief §2 (équipe de 2 ou 3), §5 `Roles-et-communication.md`", "REQ-10": "brief §5 `04-Analyse`, §8 (analyse des IoC, alertes, binaires)",
 "REQ-11": "brief §8 (chronologie à 7 colonnes), §5 `Chronologie.csv`", "REQ-12": "brief §2 (« enrichir depuis des sources ouvertes »)", "REQ-13": "brief §2 et §7 (MISP obligatoire, événement dédié)", "REQ-14": "brief §7 (relecture par API, comparaison au manifeste), §5 `Verification-MISP.md`",
 "REQ-15": "brief §2 et §9 (« au moins 25 objets liés »)", "REQ-16": "brief §9 (validateur STIX 2.1, sortie archivée, contrôle de cohérence métier)", "REQ-17": "brief §2 et §8 (identifiant et nom vérifiés dans une source officielle)", "REQ-18": "brief §2 et §8 (Diamond Model)",
 "REQ-19": "brief §2 et §8 (attribution argumentée, Admiralty A-F et 1-6 séparés)", "REQ-20": "brief §2 (impact sur les actifs), §12 (matrice CID)", "REQ-21": "brief §12 (cartographie SI) ; compétence 4", "REQ-22": "brief §10 (au moins 10 règles Sigma fondées sur l'analyse)",
 "REQ-23": "brief §10 (tests positifs et négatifs, plan et résultats), §5 `Plan-tests.md`, `Resultats-tests.csv`", "REQ-24": "brief §9 (graphe depuis le bundle final, script de régénération)", "REQ-25": "brief §12 (stratégique 2 à 3 pages)", "REQ-26": "brief §12 (tactique 8 à 12 pages)",
 "REQ-27": "brief §12 (note d'attribution)", "REQ-28": "brief §12 (note ANSSI, une page)", "REQ-29": "brief §12 (note de partage, une page, TLP)", "REQ-30": "brief §11 (journaux J1 à J5)", "REQ-31": "brief §12 (soutenance 20 min + 10 min de questions)",
 "REQ-32": "brief §13 (huit compétences)", "REQ-33": "brief §14 (manifeste avec hash)", "REQ-34": "brief §14 (cohérence entre inventaire, MISP, STIX, graphe, rapports, règles)", "REQ-35": "brief §5 `00-Pilotage`, §14 (tableau de bord à jour)",
 "REQ-36": "sujet initial : dépôt `cti-helios-energy` **obligatoire depuis le départ** (brief §14 ; l'emplacement seul était à proposer) ; confirmé par le commanditaire",
 "SUP-02": "demande du commanditaire (tour du 2026-10-07) : investigation consultable dans OpenCTI (`/dashboard/workspaces/investigations`) ; **absente du brief initial**",
 "SUP-03": "demande du commanditaire (tour du 2026-10-07) : RFI consultables dans OpenCTI (`/dashboard/cases/rfis`) ; **absente du brief initial**",
 "SUP-01": "demande du commanditaire en cours de mission (trois rubriques OpenCTI Analyses, Événements, Observations) : **n'est pas dans le brief initial**",
 "OPT-01": "brief §7 (OpenCTI « si accessible et pertinent », correspondance MISP/OpenCTI à documenter)", "OPT-02": "brief §7 (Cortex : analyseurs vérifiés et approuvés)", "OPT-03": "brief §10 (« volet Wazuh optionnel ») ; LISEZ-MOI (« volet 16 Go (Wazuh) »)",
 "OPT-04": "brief §2 (CrowdSec seulement si une fonction pertinente est démontrée)", "OPT-05": "brief §3 (dark web : consultation seulement)",
}
off = [r for k, r in M.items() if k.startswith("REQ-")]
t = "# Exigences : origine, périmètre et réconciliation 35 vers 36\n\nDate : 2026-10-06. Généré par `11-Validation/generer-exigences-origine.py`.\n\n"
t += "**Réserve de départ (B-10)** : le sujet officiel n'est pas dans le dossier. La liste ci-dessous est ma lecture du **brief du commanditaire** (première instruction de la mission, numérotée §1 à §15) et du LISEZ-MOI fourni. Le dépôt `cti-helios-energy` est obligatoire depuis le sujet initial (confirmé par le commanditaire). Q15 reste ouverte : confirmer cette liste.\n\n"
t += "## 1. Pourquoi 35 puis 36\n\n| Étape | Dénominateur officiel | Ce qui s'est passé |\n|---|---|---|\n| Début de session | 36 (REQ-01 à REQ-36) | l'ancien REQ-36 était « consultation OpenCTI en trois rubriques » : **demande supplémentaire et non exigence du sujet** ; le dépôt Git était classé à tort optionnel (OPT-06) |\n| Fin de session initiale | **35** | l'ancien REQ-36 sorti du périmètre officiel (devenu SUP-01) ; le dépôt restait **classé à tort comme optionnel** |\n| Revue de clôture | **36** | correction d'une **erreur de classement de ma part** : le dépôt est obligatoire depuis le sujet initial, OPT-06 devient **REQ-36** |\n\nLe dénominateur n'a pas été ajusté pour améliorer un pourcentage : la correction **ajoute** une exigence non satisfaite (dépôt non créé) et fait baisser le ratio. Les deux « 36 » ne désignent pas le même objet (ancien REQ-36 = OpenCTI ; REQ-36 actuel = Git). Le 35 était donc une sous-estimation, le 36 actuel est le total cohérent avec le sujet.\n\n"
def table(rows, cols):
    s = "| " + " | ".join(cols) + " |\n|" + "---|" * len(cols) + "\n"
    for r in rows: s += "| " + " | ".join(r) + " |\n"
    return s + "\n"
t += "## 2. Exigences obligatoires du sujet (36)\n\n" + table([[r["id"], r["exigence"], O[r["id"]], r["statut"], r["controles_techniques"], r["relecture_humaine_necessaire"]] for r in off], ["ID", "Exigence", "Origine", "Statut technique", "Contrôles", "Relecture humaine nécessaire"])
t += "## 3. Demandes supplémentaires OpenCTI (hors dénominateur)\n\n" + table([[M[k]["id"], M[k]["exigence"], O[k], M[k]["statut"]] for k in ("SUP-01", "SUP-02", "SUP-03")], ["ID", "Demande", "Origine", "Statut"])
t += "## 4. Volet optionnel (hors dénominateur)\n\n" + table([[M[k]["id"], M[k]["exigence"], O[k], M[k]["statut"]] for k in ("OPT-01", "OPT-02", "OPT-03", "OPT-04", "OPT-05")], ["ID", "Volet", "Origine", "Statut"])
t += "## 5. Autres améliorations internes (ni exigences ni optionnel)\n\nTravaux ajoutés par moi, comptés nulle part dans les couvertures : `Version-ATTACK.md` et `Correspondance-ATTACK-v18-v19.csv` ; `Reconciliation-tests.md` ; `Ecarts-bundle-plateformes.md` ; `Classification-et-validite.md` ; `Diagnostic-OpenCTI.md` ; `Insertion-organisation-MISP.md` ; `Options-restes-production.md` ; `Controles-exigences.csv` et son script ; captures `preuves-consultation/` ; corrections du bundle (T8 à T12) ; `Justification-25-objets-lies.md` ; `Controle-live-2026-10-07.md` ; `Audit-final-criteres.md`.\n\n"
t += "## 6. Contrôle technique et validation du commanditaire : deux choses distinctes\n\nSelon le §14 du brief, une exigence est **SATISFAITE ET CONTRÔLÉE** si le livrable existe, si le contenu attendu est présent, si la preuve est traçable, si le contrôle a été exécuté et si les limites sont écrites. Rien n'y exige l'avis du commanditaire : il est donc suivi **à part** (colonne `relu_par_commanditaire`, « non » partout à ce jour). Un contrôle technique ne remplace pas une relecture : la dernière colonne du tableau 2 dit quand un jugement humain reste utile. Le contrôle technique volontairement **partiel** est REQ-15 (statut PARTIEL), car la définition de « objets liés » n'est pas fournie : 34 objets sont extrémités d'une relation, 24 si l'on ne compte que les objets analytiques et les identités, 20 si l'on ne compte que les objets analytiques (99 si l'on compte aussi les références de conteneurs) : voir `06-STIX-Graphe/Justification-25-objets-lies.md`.\n"
open(os.path.join(B, "00-Pilotage", "Exigences-origine.md"), "w", encoding="utf-8").write(t)
print("ok", len(off))
